  1→package mdns
  2→
  3→import (
  4→	"fmt"
  5→	"net"
  6→	"strings"
  7→)
  8→
  9→const (
 10→	// localDomain 是 mDNS 的本地域（RFC 6762 §3）。
 11→	localDomain = "local."
 12→
 13→	// metaQueryName 是 DNS-SD 的服务类型枚举名（RFC 6763 §9）。
 14→	// 客户端查询它可以拿到本机提供的全部服务类型。
 15→	metaQueryName = "_services._dns-sd._udp.local."
 16→)
 17→
 18→// 记录 TTL（RFC 6762 §10）。
 19→//
 20→// 规范建议：含主机名的记录用 120 秒（主机地址可能变），
 21→// 其余记录用 75 分钟（4500 秒）。
 22→const (
 23→	ttlHost    uint32 = 120
 24→	ttlShared  uint32 = 4500
 25→	ttlGoodbye uint32 = 0
 26→)
 27→
 28→// serviceDef 是一个与实例名无关的服务定义。
 29→//
 30→// 实例名可能因为冲突而被改写（RFC 6762 §9），所以定义里不含实例名，
 31→// 由 recordSet 在生成记录时拼上当前实例名。
 32→type serviceDef struct {
 33→	// Type 是 DNS-SD 服务类型，形如 "_smb._tcp"（RFC 6763 §4.1.2）。
 34→	Type string
 35→	// Port 是 SRV 记录里的端口。DNS-SD 允许 0，表示"这个服务没有真实端口，
 36→	// 信息全在 TXT 里"（_device-info._tcp / _adisk._tcp 就是这种）。
 37→	Port uint16
 38→	// TXT 是 TXT 记录内容，每项形如 "key=value"（RFC 6763 §6.3）。
 39→	TXT []string
 40→}
 41→
 42→// typeName 返回服务类型的完整域名，如 "_smb._tcp.local."。
 43→func (d serviceDef) typeName() string {
 44→	return d.Type + "." + localDomain
 45→}
 46→
 47→// validate 检查服务定义是否能被正确编码。
 48→func (d serviceDef) validate() error {
 49→	// RFC 6763 §4.1.2：类型由 "_应用协议._传输协议" 两个 label 组成。
 50→	parts := strings.Split(d.Type, ".")
 51→	if len(parts) != 2 || !strings.HasPrefix(parts[0], "_") ||
 52→		(parts[1] != "_tcp" && parts[1] != "_udp") {
 53→		return fmt.Errorf("mdns: 服务类型 %q 不合法，应形如 \"_smb._tcp\"", d.Type)
 54→	}
 55→	if len(parts[0]) < 2 || len(parts[0]) > 16 {
 56→		// RFC 6763 §7：应用协议名（不含下划线）最长 15 个字符。
 57→		return fmt.Errorf("mdns: 服务类型 %q 的应用协议名长度非法（含下划线应为 2-16）", d.Type)
 58→	}
 59→	for _, kv := range d.TXT {
 60→		if len(kv) > maxTXTStringLen {
 61→			return fmt.Errorf("mdns: 服务 %q 的 TXT 条目 %d 字节，超过上限 %d", d.Type, len(kv), maxTXTStringLen)
 62→		}
 63→	}
 64→	return nil
 65→}
 66→
 67→// recordSet 是本 responder 宣告的全部记录。
 68→//
 69→// 实例名与主机名会在冲突时被改写，因此这里同时保存"基名"与"当前名"。
 70→type recordSet struct {
 71→	baseInstance string // 配置里的实例名
 72→	baseHost     string // 配置里的主机 label（不含 .local.）
 73→
 74→	instance  string // 当前实例名
 75→	hostLabel string // 当前主机 label
 76→
 77→	defs []serviceDef
 78→}
 79→
 80→func newRecordSet(instance, hostLabel string, defs []serviceDef) (*recordSet, error) {
 81→	for _, d := range defs {
 82→		if err := d.validate(); err != nil {
 83→			return nil, err
 84→		}
 85→	}
 86→	return &recordSet{
 87→		baseInstance: instance,
 88→		baseHost:     hostLabel,
 89→		instance:     instance,
 90→		hostLabel:    hostLabel,
 91→		defs:         defs,
 92→	}, nil
 93→}
 94→
 95→// hostname 返回主机名，如 "MYBOX.local."。
 96→func (rs *recordSet) hostname() string {
 97→	return EscapeLabel(rs.hostLabel) + "." + localDomain
 98→}
 99→
100→// instanceName 返回某个服务的实例名，如 "MYBOX._smb._tcp.local."。
101→func (rs *recordSet) instanceName(d serviceDef) string {
102→	return EscapeLabel(rs.instance) + "." + d.typeName()
103→}
104→
105→// rename 按 RFC 6762 §9 的建议改名：在原名后追加 "-2"、"-3" …
106→//
107→// n 是第几次冲突（从 1 开始），n=1 得到 "-2"。
108→func (rs *recordSet) rename(n int) {
109→	suffix := fmt.Sprintf("-%d", n+1)
110→	rs.instance = truncateLabel(rs.baseInstance, maxLabelLen-len(suffix)) + suffix
111→	rs.hostLabel = truncateLabel(rs.baseHost, maxLabelLen-len(suffix)) + suffix
112→}
113→
114→// truncateLabel 按字节截断，保证加上后缀后仍然是合法的 DNS label。
115→func truncateLabel(s string, max int) string {
116→	if len(s) <= max {
117→		return s
118→	}
119→	// 按 UTF-8 边界回退，避免把一个多字节字符切成两半。
120→	b := []byte(s[:max])
121→	for len(b) > 0 && b[len(b)-1]&0xc0 == 0x80 {
122→		b = b[:len(b)-1]
123→	}
124→	return string(b)
125→}
126→
127→// ownsName 判断某个名字是否由本 responder 负责应答（大小写不敏感）。
128→func (rs *recordSet) ownsName(name string) bool {
129→	if EqualName(name, rs.hostname()) || EqualName(name, metaQueryName) {
130→		return true
131→	}
132→	for _, d := range rs.defs {
133→		if EqualName(name, d.typeName()) || EqualName(name, rs.instanceName(d)) {
134→			return true
135→		}
136→	}
137→	return false
138→}
139→
140→// uniqueNames 返回需要 probing 的名字（RFC 6762 §8.1）。
141→//
142→// 只有"唯一记录集"才需要探测：主机名与各服务实例名。
143→// 服务类型的 PTR 是共享记录，多台机器本来就该同时存在，不参与探测。
144→func (rs *recordSet) uniqueNames() []string {
145→	names := make([]string, 0, len(rs.defs)+1)
146→	names = append(names, rs.hostname())
147→	for _, d := range rs.defs {
148→		names = append(names, rs.instanceName(d))
149→	}
150→	return names
151→}
152→
153→// serviceRecords 返回与网卡无关的记录：
154→// 服务类型枚举 PTR（元查询）、服务实例 PTR、SRV、TXT。
155→func (rs *recordSet) serviceRecords() []Record {
156→	out := make([]Record, 0, len(rs.defs)*4)
157→	seenType := make(map[string]bool, len(rs.defs))
158→
159→	for _, d := range rs.defs {
160→		typeName := d.typeName()
161→		inst := rs.instanceName(d)
162→
163→		// RFC 6763 §9：_services._dns-sd._udp.local. PTR -> 服务类型。
164→		// 同一类型只需要一条。
165→		if !seenType[strings.ToLower(typeName)] {
166→			seenType[strings.ToLower(typeName)] = true
167→			out = append(out, Record{
168→				Name: metaQueryName, Class: ClassIN, TTL: ttlShared,
169→				Data: PTR{Target: typeName},
170→			})
171→		}
172→
173→		// RFC 6763 §4.1：服务类型 PTR -> 服务实例。共享记录，不置 cache-flush。
174→		out = append(out, Record{
175→			Name: typeName, Class: ClassIN, TTL: ttlShared,
176→			Data: PTR{Target: inst},
177→		})
178→
179→		// SRV / TXT 是本实例独占的唯一记录，置 cache-flush（RFC 6762 §10.2）。
180→		out = append(out, Record{
181→			Name: inst, Class: ClassIN, CacheFlush: true, TTL: ttlHost,
182→			Data: SRV{Priority: 0, Weight: 0, Port: d.Port, Target: rs.hostname()},
183→		})
184→		out = append(out, Record{
185→			Name: inst, Class: ClassIN, CacheFlush: true, TTL: ttlShared,
186→			Data: TXT{Strings: d.TXT},
187→		})
188→	}
189→	return out
190→}
191→
192→// addressRecords 返回某张网卡上的 A/AAAA 记录。
193→//
194→// RFC 6762 §6：应答必须只包含在收包链路上有效的地址，
195→// 所以地址记录是按网卡生成的，不能一股脑全发出去。
196→func (rs *recordSet) addressRecords(ifi *net.Interface) []Record {
197→	v4, v6 := interfaceIPs(ifi)
198→	out := make([]Record, 0, len(v4)+len(v6))
199→	host := rs.hostname()
200→	for _, ip := range v4 {
201→		out = append(out, Record{
202→			Name: host, Class: ClassIN, CacheFlush: true, TTL: ttlHost,
203→			Data: A{IP: ip},
204→		})
205→	}
206→	for _, ip := range v6 {
207→		out = append(out, Record{
208→			Name: host, Class: ClassIN, CacheFlush: true, TTL: ttlHost,
209→			Data: AAAA{IP: ip},
210→		})
211→	}
212→	return out
213→}
214→
215→// hostNSEC 返回主机名的否定回答记录（RFC 6762 §6.1）：
216→// 明确告诉对方"这个名字上只有这些类型"，省掉客户端对不存在类型的重试
217→// （典型场景：只有 IPv4 的机器，让 macOS 别再等 AAAA）。
218→func (rs *recordSet) hostNSEC(hasV4, hasV6 bool) (Record, bool) {
219→	var types []Type
220→	if hasV4 {
221→		types = append(types, TypeA)
222→	}
223→	if hasV6 {
224→		types = append(types, TypeAAAA)
225→	}
226→	if len(types) == 0 {
227→		return Record{}, false
228→	}
229→	host := rs.hostname()
230→	return Record{
231→		Name: host, Class: ClassIN, CacheFlush: true, TTL: ttlHost,
232→		Data: NSEC{NextDomain: host, Types: types},
233→	}, true
234→}
235→
236→// instanceNSECs 返回各服务实例名的否定回答记录：实例名上只有 TXT 与 SRV。
237→func (rs *recordSet) instanceNSECs() []Record {
238→	out := make([]Record, 0, len(rs.defs))
239→	for _, d := range rs.defs {
240→		inst := rs.instanceName(d)
241→		out = append(out, Record{
242→			Name: inst, Class: ClassIN, CacheFlush: true, TTL: ttlHost,
243→			Data: NSEC{NextDomain: inst, Types: []Type{TypeTXT, TypeSRV}},
244→		})
245→	}
246→	return out
247→}
248→
249→// withTTL 复制一份记录并统一改写 TTL。goodbye 报文用 TTL=0（RFC 6762 §10.1）。
250→func withTTL(records []Record, ttl uint32) []Record {
251→	out := make([]Record, len(records))
252→	copy(out, records)
253→	for i := range out {
254→		out[i].TTL = ttl
255→	}
256→	return out
257→}
