  9→	"github.com/finalappstore/stupidsamba/internal/vfs"
 10→)
 11→
 12→func init() {
 13→	register(wire.CommandCreate, true, true, handleCreate)
 14→}
 15→
 16→// handleCreate 处理 SMB2 CREATE（MS-SMB2 §3.3.5.9）。
 17→//
 18→// CREATE 是整个协议里语义最重的命令：它同时承担 open / create / truncate /
 19→// mkdir / delete-on-close 五件事，具体做哪件由 CreateDisposition 与
 20→// CreateOptions 的组合决定。这里把这些组合翻译成 vfs.OpenRequest，
 21→// 真正的路径校验与 IO 由 VFS 层负责（AGENTS.md §8：路径穿越防御统一在 VFS）。
 22→func handleCreate(ctx *Context) error {
 23→	req, err := wire.ParseCreateRequest(ctx.Msg)
 24→	if err != nil {
 25→		ctx.Log.Debug("CREATE 请求解析失败", "err", err)
 26→		return status.InvalidParameter
 27→	}
 28→
 29→	if ctx.Tree.IsIPC() {
 30→		return createPipe(ctx, req)
 31→	}
 32→	return createFile(ctx, req)
 33→}
 34→
 35→// createFile 在磁盘共享上打开/创建对象。
 36→func createFile(ctx *Context, req *wire.CreateRequest) error {
 37→	fs := ctx.Tree.FS()
 38→	if fs == nil {
 39→		return status.NetworkNameDeleted
 40→	}
 41→
 42→	// 不支持按 FileId 打开（需要一张全卷 FileId→路径表，且客户端有回退路径）。
 43→	if req.CreateOptions&wire.FileOpenByFileID != 0 {
 44→		return status.NotSupported
 45→	}
 46→
 47→	path, stream, err := splitCreateName(req.Name)
 48→	if err != nil {
 49→		return err
 50→	}
 51→
 52→	// GENERIC_* 要先展开成具体位，后续判定才有意义（MS-DTYP §2.4.3）。
 53→	access := req.DesiredAccess.Expand()
 54→	// MAXIMUM_ALLOWED：按本树允许的上限授予。授权依据是配置，不是宿主 ACL。
 55→	if access&wire.MaximumAllowed != 0 {
 56→		access = maximalAccessFor(ctx.Tree)
 57→	}
 58→
 59→	writing := access&(wire.FileWriteData|wire.FileAppendData|wire.FileWriteEA|
 60→		wire.FileWriteAttributes|wire.Delete|wire.WriteDAC|wire.WriteOwner) != 0
 61→	// 除 FILE_OPEN 外的所有 disposition 都会改动文件系统。
 62→	mutating := req.CreateDisposition != wire.FileOpen
 63→	if writing || mutating {
 64→		if err := ctx.RequireWritable(); err != nil {
 65→			return err
 66→		}
 67→	}
 68→
 69→	openReq := &vfs.OpenRequest{
 70→		Path:           path,
 71→		Stream:         stream,
 72→		Flags:          openFlags(access, req.CreateOptions),
 73→		Disposition:    vfs.Disposition(req.CreateDisposition),
 74→		FileAttributes: uint32(req.FileAttributes),
 75→	}
 76→
 77→	h, action, err := fs.Open(openReq)
 78→	if err != nil {
 79→		ctx.Log.Debug("CREATE 打开失败", "path", path, "stream", stream, "err", err)
 80→		return createStatus(err, req.CreateDisposition)
 81→	}
 82→
 83→	attr, err := h.Stat()
 84→	if err != nil {
 85→		_ = h.Close()
 86→		return status.FromVFSError(err)
 87→	}
 88→
 89→	isDir := attr.FileAttributes&vfs.FileAttributeDirectory != 0
 90→	// FILE_DIRECTORY_FILE / FILE_NON_DIRECTORY_FILE 是硬性断言，
 91→	// VFS 后端可能没能力提前判断，这里兜底（MS-SMB2 §3.3.5.9）。
 92→	if req.CreateOptions&wire.FileDirectoryFile != 0 && !isDir {
 93→		_ = h.Close()
 94→		return status.NotADirectory
 95→	}
 96→	if req.CreateOptions&wire.FileNonDirectoryFile != 0 && isDir {
 97→		_ = h.Close()
 98→		return status.FileIsADirectory
 99→	}
100→
101→	open := &Open{
102→		Tree:           ctx.Tree,
103→		Path:           path,
104→		Stream:         stream,
105→		Handle:         h,
106→		IsDir:          isDir,
107→		GrantedAccess:  access,
108→		ShareAccess:    req.ShareAccess,
109→		CreateAction:   wire.CreateAction(action),
110→		CreateOptions:  req.CreateOptions,
111→		FileAttributes: wire.FileAttributes(attr.FileAttributes),
112→	}
113→	if req.CreateOptions&wire.FileDeleteOnClose != 0 {
114→		if err := ctx.RequireWritable(); err != nil {
115→			_ = h.Close()
116→			return err
117→		}
118→		open.SetDeleteOnClose(true)
119→	}
120→
121→	if st := ctx.Session.AddOpen(open); st != status.Success {
122→		_ = h.Close()
123→		return st
124→	}
125→	ctx.Chain.LastOpen = open
126→
127→	resp := &wire.CreateResponse{
128→		// 不实现 oplock/lease：一律回 NONE。客户端会退化成不缓存，
129→		// 正确性不受影响（protocol-notes §9）。
130→		OplockLevel:    wire.OplockLevelNone,
131→		CreateAction:   open.CreateAction,
132→		CreationTime:   vfs.TimeToFiletime(attr.CreateTime),
133→		LastAccessTime: vfs.TimeToFiletime(attr.AccessTime),
134→		LastWriteTime:  vfs.TimeToFiletime(attr.WriteTime),
135→		ChangeTime:     vfs.TimeToFiletime(attr.ChangeTime),
136→		AllocationSize: uint64(attr.Alloc),
137→		EndOfFile:      uint64(attr.Size),
138→		FileAttributes: wire.FileAttributes(attr.FileAttributes),
139→		FileID:         wire.FileID{Persistent: open.Persistent, Volatile: open.Volatile},
140→		Contexts:       createResponseContexts(req, attr),
141→	}
142→
143→	out, err := resp.Append(ctx.Out)
144→	if err != nil {
145→		ctx.Log.Error("编码 CREATE Response 失败", "err", err)
146→		return status.InsuffServerResources
147→	}
148→	ctx.Out = out
149→
150→	ctx.Log.Debug("CREATE",
151→		"share", ctx.Tree.Share.Name, "path", path, "dir", isDir,
152→		"action", action, "fid", open.Volatile)
153→	return nil
154→}
155→
156→// createPipe 在 IPC$ 上打开一个命名管道。
157→func createPipe(ctx *Context, req *wire.CreateRequest) error {
158→	opener := ctx.Conn.Settings.Pipes
159→	if opener == nil {
160→		// 管道后端尚未装配：报「没有这个对象」而不是 NOT_SUPPORTED，
161→		// 客户端会当成共享枚举不可用而优雅退化。
162→		return status.ObjectNameNotFound
163→	}
164→
165→	// 管道名不含路径分隔符，且大小写不敏感。
166→	name := strings.ToLower(strings.Trim(req.Name, `\`))
167→	if name == "" || strings.ContainsAny(name, `\/`) {
168→		return status.ObjectNameInvalid
169→	}
170→
171→	pipe, err := opener.OpenPipe(name, ctx.Session.Identity())
172→	if err != nil {
173→		if errors.Is(err, ErrNoSuchPipe) {
174→			ctx.Log.Debug("请求了未提供的命名管道", "pipe", name)
175→			return status.ObjectNameNotFound
176→		}
177→		ctx.Log.Warn("打开命名管道失败", "pipe", name, "err", err)
178→		return status.FromVFSError(err)
179→	}
180→
181→	open := &Open{
182→		Tree:          ctx.Tree,
183→		Path:          name,
184→		Pipe:          pipe,
185→		GrantedAccess: req.DesiredAccess.Expand(),
186→		ShareAccess:   req.ShareAccess,
187→		CreateAction:  wire.FileOpened,
188→		CreateOptions: req.CreateOptions,
189→		// 管道在 Windows 上报为 NORMAL。
190→		FileAttributes: wire.FileAttributeNormal,
191→	}
192→	if st := ctx.Session.AddOpen(open); st != status.Success {
193→		_ = pipe.Close()
194→		return st
195→	}
196→	ctx.Chain.LastOpen = open
197→
198→	// 管道没有真正的时间戳与长度，全部回 0 —— 客户端不看这些字段。
199→	resp := &wire.CreateResponse{
200→		OplockLevel:    wire.OplockLevelNone,
201→		CreateAction:   wire.FileOpened,
202→		FileAttributes: wire.FileAttributeNormal,
203→		FileID:         wire.FileID{Persistent: open.Persistent, Volatile: open.Volatile},
204→	}
205→	out, err := resp.Append(ctx.Out)
206→	if err != nil {
207→		return status.InsuffServerResources
208→	}
209→	ctx.Out = out
210→
211→	ctx.Log.Debug("打开命名管道", "pipe", name, "fid", open.Volatile)
212→	return nil
213→}
214→
215→// splitCreateName 把 CREATE 的 Name 拆成「共享内相对路径」与「流名」。
216→//
217→// 线格式用反斜杠分隔且无前导反斜杠（protocol-notes §8），VFS 用正斜杠。
218→// 流名语法是 `path:stream:$DATA`（MS-FSCC §2.1.5.4）。
219→//
220→// 真正的路径穿越防御在 VFS 层（AGENTS.md §8），这里只做**语法**校验：
221→// 拒绝绝对路径与显然畸形的输入，避免把垃圾喂给下层。
222→func splitCreateName(name string) (path, stream string, err error) {
223→	if strings.ContainsRune(name, 0) {
224→		return "", "", status.ObjectNameInvalid
225→	}
226→	// 客户端偶尔会带前导反斜杠，容忍之。
227→	name = strings.TrimPrefix(name, `\`)
228→	name = strings.ReplaceAll(name, `\`, "/")
229→
230→	if i := strings.IndexByte(name, ':'); i >= 0 {
231→		path, stream = name[:i], name[i+1:]
232→		// 去掉 `:$DATA` 后缀；类型不是 $DATA 的流我们不支持。
233→		if j := strings.IndexByte(stream, ':'); j >= 0 {
234→			if !strings.EqualFold(stream[j:], ":$DATA") {
235→				return "", "", status.NotSupported
236→			}
237→			stream = stream[:j]
238→		}
239→		if stream == "" {
240→			// `file::$DATA` 就是主数据流。
241→			stream = ""
242→		}
243→	} else {
244→		path = name
245→	}
246→
247→	// vfs.CleanPath 负责规范化并拒绝 ".."、绝对路径等越界写法。
248→	clean, cerr := vfs.CleanPath(path)
249→	if cerr != nil {
250→		return "", "", status.ObjectPathInvalid
251→	}
252→	return clean, stream, nil
253→}
254→
255→// openFlags 把 SMB 的 DesiredAccess/CreateOptions 翻译成 vfs.OpenFlags。
256→func openFlags(access wire.Access, opts wire.CreateOptions) vfs.OpenFlags {
257→	var f vfs.OpenFlags
258→
259→	if access&(wire.FileReadData|wire.FileExecute) != 0 {
260→		f |= vfs.OpenRead
261→	}
262→	if access&(wire.FileWriteData) != 0 {
263→		f |= vfs.OpenWrite
264→	}
265→	if access&wire.FileAppendData != 0 {
266→		f |= vfs.OpenAppend
267→	}
268→	// 只要了属性/EA/ACL 而没要数据流：告诉后端可以走轻量路径。
269→	// Explorer 与 Finder 会为列表里的每个文件做这种探测，量很大。
270→	if f == 0 {
271→		f |= vfs.OpenAttrOnly
272→	}
273→
274→	if opts&wire.FileDirectoryFile != 0 {
275→		f |= vfs.OpenDirectory
276→	}
277→	if opts&wire.FileNonDirectoryFile != 0 {
278→		f |= vfs.OpenNonDirectory
279→	}
280→	if opts&wire.FileOpenReparsePoint != 0 {
281→		f |= vfs.OpenNoFollow
282→	}
283→	if opts&wire.FileWriteThrough != 0 {
284→		f |= vfs.OpenWriteThrough
285→	}
286→	if opts&wire.FileDeleteOnClose != 0 {
287→		f |= vfs.OpenDeleteOnClose
288→	}
289→	return f
290→}
291→
292→// maximalAccessFor 返回 MAXIMUM_ALLOWED 在本树上应当授予的访问掩码。
293→func maximalAccessFor(t *Tree) wire.Access {
294→	if t.Writable() {
295→		return wire.Access(wire.MaximalAccessReadWrite)
296→	}
297→	return wire.Access(wire.MaximalAccessReadOnly)
298→}
299→
300→// createStatus 把 VFS 错误映射为 CREATE 语境下的 NTSTATUS。
301→//
302→// 与通用映射的差别只有一处：CREATE 语境里 ErrExist 的含义取决于
303→// disposition —— FILE_CREATE 下是「已存在」，其它情况下是「名字冲突」。
304→func createStatus(err error, disp wire.CreateDisposition) status.Status {
305→	if errors.Is(err, vfs.ErrExist) && disp == wire.FileCreate {
306→		return status.ObjectNameCollision
307→	}
308→	return status.FromVFSError(err)
309→}
310→
311→// createResponseContexts 生成要回给客户端的 create context 链。
312→//
313→// 目前只支持 "QFid"（请求稳定 FileId）—— macOS 与 Windows 都会带，
314→// 回它可以让客户端少发一轮 QUERY_INFO。其余 context（DHnQ/RqLs/AAPL）
315→// 属于后续阶段，**不认识的 context 必须静默忽略**而不是报错
316→// （MS-SMB2 §3.3.5.9：服务端忽略不支持的 create context）。
317→func createResponseContexts(req *wire.CreateRequest, attr *vfs.Attr) []wire.CreateContext {
318→	if _, ok := wire.FindCreateContext(req.Contexts, wire.CreateContextQFid); !ok {
319→		return nil
320→	}
321→	return []wire.CreateContext{{
322→		Name: wire.CreateContextQFid,
323→		Data: wire.DiskIDContext{DiskFileID: attr.FileID}.Encode(),
324→	}}
325→}
