179→	}
180→
181→	open := &Open{
182→		Tree:          ctx.Tree,
183→		Path:          name,
184→		Pipe:          pipe,
185→		GrantedAccess: req.DesiredAccess.Expand(),
186→		ShareAccess:   req.ShareAccess,
187→		CreateAction:  wire.FileOpened,
188→		CreateOptions: req.CreateOptions,
189→		// 管道在 Windows 上报为 NORMAL。
190→		FileAttributes: wire.FileAttributeNormal,
191→	}
192→	if st := ctx.Session.AddOpen(open); st != status.Success {
193→		_ = pipe.Close()
194→		return st
195→	}
196→	ctx.Chain.LastOpen = open
197→
198→	// 管道没有真正的时间戳与长度，全部回 0 —— 客户端不看这些字段。
199→	resp := &wire.CreateResponse{
200→		OplockLevel:    wire.OplockLevelNone,
201→		CreateAction:   wire.FileOpened,
202→		FileAttributes: wire.FileAttributeNormal,
203→		FileID:         wire.FileID{Persistent: open.Persistent, Volatile: open.Volatile},
204→	}
205→	out, err := resp.Append(ctx.Out)
206→	if err != nil {
207→		return status.InsuffServerResources
208→	}
209→	ctx.Out = out
210→
211→	ctx.Log.Debug("打开命名管道", "pipe", name, "fid", open.Volatile)
212→	return nil
213→}
214→
215→// splitCreateName 把 CREATE 的 Name 拆成「共享内相对路径」与「流名」。
216→//
217→// 线格式用反斜杠分隔且无前导反斜杠（protocol-notes §8），VFS 用正斜杠。
218→// 流名语法是 `path:stream:$DATA`（MS-FSCC §2.1.5.4）。
219→//
220→// 真正的路径穿越防御在 VFS 层（AGENTS.md §8），这里只做**语法**校验：
221→// 拒绝绝对路径与显然畸形的输入，避免把垃圾喂给下层。
222→func splitCreateName(name string) (path, stream string, err error) {
223→	if strings.ContainsRune(name, 0) {
224→		return "", "", status.ObjectNameInvalid
225→	}
226→	// 客户端偶尔会带前导反斜杠，容忍之。
227→	name = strings.TrimPrefix(name, `\`)
228→	name = strings.ReplaceAll(name, `\`, "/")
229→
230→	if i := strings.IndexByte(name, ':'); i >= 0 {
231→		path, stream = name[:i], name[i+1:]
232→		// 去掉 `:$DATA` 后缀；类型不是 $DATA 的流我们不支持。
233→		if j := strings.IndexByte(stream, ':'); j >= 0 {
234→			if !strings.EqualFold(stream[j:], ":$DATA") {
235→				return "", "", status.NotSupported
236→			}
237→			stream = stream[:j]
238→		}
239→		if stream == "" {
240→			// `file::$DATA` 就是主数据流。
241→			stream = ""
242→		}
243→	} else {
244→		path = name
245→	}
246→
247→	// vfs.CleanPath 负责规范化并拒绝 ".."、绝对路径等越界写法。
248→	clean, cerr := vfs.CleanPath(path)
249→	if cerr != nil {
250→		return "", "", status.ObjectPathInvalid
251→	}
252→	return clean, stream, nil
253→}
254→
255→// openFlags 把 SMB 的 DesiredAccess/CreateOptions 翻译成 vfs.OpenFlags。
256→func openFlags(access wire.Access, opts wire.CreateOptions) vfs.OpenFlags {
257→	var f vfs.OpenFlags
258→
259→	if access&(wire.FileReadData|wire.FileExecute) != 0 {
260→		f |= vfs.OpenRead
261→	}
262→	if access&(wire.FileWriteData) != 0 {
263→		f |= vfs.OpenWrite
264→	}
265→	if access&wire.FileAppendData != 0 {
266→		f |= vfs.OpenAppend
267→	}
268→	// 只要了属性/EA/ACL 而没要数据流：告诉后端可以走轻量路径。
269→	// Explorer 与 Finder 会为列表里的每个文件做这种探测，量很大。
270→	if f == 0 {
271→		f |= vfs.OpenAttrOnly
272→	}
273→
274→	if opts&wire.FileDirectoryFile != 0 {
275→		f |= vfs.OpenDirectory
276→	}
277→	if opts&wire.FileNonDirectoryFile != 0 {
278→		f |= vfs.OpenNonDirectory
279→	}
280→	if opts&wire.FileOpenReparsePoint != 0 {
281→		f |= vfs.OpenNoFollow
282→	}
283→	if opts&wire.FileWriteThrough != 0 {
284→		f |= vfs.OpenWriteThrough
285→	}
286→	if opts&wire.FileDeleteOnClose != 0 {
287→		f |= vfs.OpenDeleteOnClose
288→	}
289→	return f
290→}
291→
292→// maximalAccessFor 返回 MAXIMUM_ALLOWED 在本树上应当授予的访问掩码。
293→func maximalAccessFor(t *Tree) wire.Access {
294→	if t.Writable() {
295→		return wire.Access(wire.MaximalAccessReadWrite)
296→	}
297→	return wire.Access(wire.MaximalAccessReadOnly)
298→}
299→
300→// createStatus 把 VFS 错误映射为 CREATE 语境下的 NTSTATUS。
301→//
302→// 与通用映射的差别只有一处：CREATE 语境里 ErrExist 的含义取决于
303→// disposition —— FILE_CREATE 下是「已存在」，其它情况下是「名字冲突」。
304→func createStatus(err error, disp wire.CreateDisposition) status.Status {
305→	if errors.Is(err, vfs.ErrExist) && disp == wire.FileCreate {
306→		return status.ObjectNameCollision
307→	}
308→	return status.FromVFSError(err)
309→}
310→
311→// createResponseContexts 生成要回给客户端的 create context 链。
312→//
313→// 目前只支持 "QFid"（请求稳定 FileId）—— macOS 与 Windows 都会带，
314→// 回它可以让客户端少发一轮 QUERY_INFO。其余 context（DHnQ/RqLs/AAPL）
315→// 属于后续阶段，**不认识的 context 必须静默忽略**而不是报错
316→// （MS-SMB2 §3.3.5.9：服务端忽略不支持的 create context）。
317→func createResponseContexts(req *wire.CreateRequest, attr *vfs.Attr) []wire.CreateContext {
318→	if _, ok := wire.FindCreateContext(req.Contexts, wire.CreateContextQFid); !ok {
319→		return nil
320→	}
321→	return []wire.CreateContext{{
322→		Name: wire.CreateContextQFid,
323→		Data: wire.DiskIDContext{DiskFileID: attr.FileID}.Encode(),
324→	}}
325→}
