 1→package mdns
 2→
 3→import (
 4→	"fmt"
 5→	"log/slog"
 6→	"strings"
 7→
 8→	"github.com/finalappstore/stupidsamba/internal/config"
 9→)
10→
11→// New 根据配置构造一个 mDNS responder。
12→//
13→// 本包与 SMB 协议层完全解耦（AGENTS.md §5）：只吃配置、端口和共享列表，
14→// 不 import internal/server 或 internal/smb 里的任何东西。
15→//
16→// port 是 SMB 服务端口，用于 _smb._tcp 的 SRV 记录。
17→func New(cfg config.MDNS, port int, shares []config.Share) (*Responder, error) {
18→	if port < 1 || port > 65535 {
19→		return nil, fmt.Errorf("mdns: 端口 %d 不在 1-65535 范围内", port)
20→	}
21→	instance := strings.TrimSpace(cfg.Instance)
22→	if instance == "" {
23→		return nil, fmt.Errorf("mdns: 实例名为空（config.ApplyDefaults 会用 server.name 填充，请检查配置加载流程）")
24→	}
25→
26→	defs := []serviceDef{smbServiceDef(uint16(port))}
27→
28→	if cfg.Apple.Enabled {
29→		model := cfg.Apple.Model
30→		if model == "" {
31→			model = config.DefaultAppleModel
32→		}
33→		defs = append(defs, deviceInfoServiceDef(model))
34→
35→		if cfg.Apple.AdvertiseTimeMachine {
36→			if def, ok := adiskServiceDef(timeMachineVolumes(shares)); ok {
37→				defs = append(defs, def)
38→			}
39→		}
40→	}
41→
42→	rs, err := newRecordSet(instance, hostLabel(instance), defs)
43→	if err != nil {
44→		return nil, err
45→	}
46→
47→	return &Responder{
48→		rs:         rs,
49→		ifaceNames: cfg.Interfaces,
50→		log:        slog.Default(),
51→		conflictCh: make(chan struct{}, 1),
52→	}, nil
53→}
54→
55→// timeMachineVolumes 挑出标记为 Time Machine 目标的共享名。
56→func timeMachineVolumes(shares []config.Share) []string {
57→	var out []string
58→	for i := range shares {
59→		if shares[i].TimeMachine {
60→			out = append(out, shares[i].Name)
61→		}
62→	}
63→	return out
64→}
65→
66→// hostLabel 把实例名转换成可用作主机名的 DNS label。
67→//
68→// DNS-SD 实例名允许空格等任意 UTF-8（RFC 6763 §4.1.1），但主机名（A/AAAA
69→// 记录的名字）会被人直接敲进地址栏，保守起见只保留 [A-Za-z0-9-]，
70→// 其余字符换成连字符（RFC 1123 §2.1 的主机名字符集）。
71→func hostLabel(instance string) string {
72→	var sb strings.Builder
73→	for _, ch := range instance {
74→		switch {
75→		case ch >= 'a' && ch <= 'z', ch >= 'A' && ch <= 'Z', ch >= '0' && ch <= '9':
76→			sb.WriteRune(ch)
77→		case ch == '-' || ch == '_':
78→			sb.WriteByte('-')
79→		default:
80→			// 非 ASCII 与标点统统折叠成一个连字符。
81→			sb.WriteByte('-')
82→		}
83→	}
84→	// 去掉首尾连字符：主机名不能以连字符开头或结尾。
85→	label := strings.Trim(sb.String(), "-")
86→	if label == "" {
87→		label = "stupidsamba"
88→	}
89→	return truncateLabel(label, maxLabelLen)
90→}
91→

