  1→package vfs
  2→
  3→// optional.go —— **可选能力接口**。
  4→//
  5→// 为什么不直接加进 fs.go 的 Handle/FileSystem：那两个接口是跨模块契约
  6→// （AGENTS.md §7.3），每加一个方法所有实现都得跟着改。而这里的能力
  7→// 是「后端支持就用，不支持就退化」的性质，用可选接口 + 类型断言表达更合适：
  8→//
  9→//	if d, ok := handle.(vfs.DeleteOnCloser); ok {
 10→//	    err = d.SetDeleteOnClose(true)
 11→//	} else {
 12→//	    err = vfs.ErrNotSupported
 13→//	}
 14→//
 15→// 这也是 Go 标准库的惯用法（io.ReaderFrom / http.Flusher 都是这个套路）。
 16→
 17→import "os"
 18→
 19→// DeleteOnCloser 让已打开的句柄可以**事后**被标记为「关闭时删除」。
 20→//
 21→// 对应 SMB2 SET_INFO 的 FileDispositionInformation（MS-FSCC §2.4.11）：
 22→// 客户端删文件的标准流程是 CREATE(带 DELETE 权限) → SET_INFO(DeletePending=1)
 23→// → CLOSE，而不是发一个「删除」命令。CREATE 时的 FILE_DELETE_ON_CLOSE
 24→// 只是另一条路径。
 25→type DeleteOnCloser interface {
 26→	SetDeleteOnClose(del bool) error
 27→}
 28→
 29→// SparseFile 是稀疏文件能力。
 30→//
 31→// Time Machine 的 .sparsebundle 由大量固定大小的 band 文件组成，
 32→// 备份过期回收时会把 band 里的区间置零。没有打洞能力的话，
 33→// 备份卷只会越来越大、永远不会缩小（AGENTS.md §2 阶段二）。
 34→//
 35→// 对应 SMB2 IOCTL 的 FSCTL_SET_ZERO_DATA / FSCTL_SET_SPARSE。
 36→type SparseFile interface {
 37→	// PunchHole 把 [off, off+length) 释放成空洞，读回来是零。
 38→	// 文件逻辑长度不变。
 39→	PunchHole(off, length int64) error
 40→
 41→	// Preallocate 预留 [off, off+length) 的空间但不改变文件逻辑长度
 42→	// （对应 AllocationSize / AlSi create context）。
 43→	Preallocate(off, length int64) error
 44→}
