  1→package command
  2→
  3→import (
  4→	"errors"
  5→	"io"
  6→
  7→	"github.com/finalappstore/stupidsamba/internal/smb/status"
  8→	"github.com/finalappstore/stupidsamba/internal/smb/wire"
  9→	"github.com/finalappstore/stupidsamba/internal/vfs"
 10→)
 11→
 12→func init() {
 13→	register(wire.CommandQueryDirectory, true, true, handleQueryDirectory)
 14→}
 15→
 16→// handleQueryDirectory 处理 SMB2 QUERY_DIRECTORY（MS-SMB2 §3.3.5.18）。
 17→//
 18→// 语义要点（protocol-notes §9，非常容易踩错）：
 19→//   - 搜索模式只在**首次**（或带 SMB2_RESTART_SCANS 时）携带，
 20→//     后续调用沿用同一句柄上的模式，枚举位置也保存在句柄里；
 21→//   - 首次调用就没有任何匹配 → STATUS_NO_SUCH_FILE；
 22→//   - 之前吐过条目、这次没有了 → STATUS_NO_MORE_FILES；
 23→//     两者搞混会让客户端要么少显示文件、要么无限循环。
 24→//   - 输出必须 8 字节对齐并回填 NextEntryOffset，由 wire.DirEntryWriter 负责。
 25→func handleQueryDirectory(ctx *Context) error {
 26→	req, err := wire.ParseQueryDirectoryRequest(ctx.Msg)
 27→	if err != nil {
 28→		return status.InvalidParameter
 29→	}
 30→
 31→	open, err := ctx.resolveOpen(req.FileID)
 32→	if err != nil {
 33→		return err
 34→	}
 35→	if !open.IsDir {
 36→		return status.InvalidParameter
 37→	}
 38→	if open.GrantedAccess&wire.FileReadData == 0 {
 39→		// FILE_LIST_DIRECTORY 与 FILE_READ_DATA 是同一个位。
 40→		return status.AccessDenied
 41→	}
 42→	if open.Handle == nil {
 43→		return status.FileClosed
 44→	}
 45→
 46→	// 输出上限同时受客户端请求与协商出的 MaxTransactSize 约束
 47→	// （AGENTS.md §8：目录枚举缓冲必须有上限）。
 48→	maxOut := int(req.OutputBufferLength)
 49→	if maxOut <= 0 {
 50→		return status.InvalidParameter
 51→	}
 52→	if maxOut > int(ctx.Conn.MaxTransactSize) {
 53→		maxOut = int(ctx.Conn.MaxTransactSize)
 54→	}
 55→
 56→	pattern, first := open.DirScan(req.FileName, req.Restart())
 57→
 58→	// SMB2_RETURN_SINGLE_ENTRY：一次只要一条。
 59→	batch := 0
 60→	if req.SingleEntry() {
 61→		batch = 1
 62→	}
 63→
 64→	entries, rerr := open.ReadDir(pattern, req.Restart(), batch)
 65→	if rerr != nil && !errors.Is(rerr, io.EOF) {
 66→		return status.FromVFSError(rerr)
 67→	}
 68→	if len(entries) == 0 {
 69→		return noMoreFiles(first)
 70→	}
 71→
 72→	w := wire.NewDirEntryWriter(req.FileInformationClass, maxOut)
 73→	written := 0
 74→	for i := range entries {
 75→		ok, werr := w.Add(dirEntry(&entries[i]))
 76→		if werr != nil {
 77→			// 不认识的 information class。
 78→			return status.InvalidInfoClass
 79→		}
 80→		if !ok {
 81→			// 缓冲放不下了：把没写进去的条目退回句柄，下一轮再来。
 82→			open.UnreadDir(entries[i:])
 83→			break
 84→		}
 85→		written++
 86→	}
 87→
 88→	if written == 0 {
 89→		// 一条都放不下：客户端给的缓冲太小，连一个条目都装不了。
 90→		return status.InfoLengthMismatch
 91→	}
 92→
 93→	resp := &wire.QueryDirectoryResponse{Buffer: w.Bytes()}
 94→	out, aerr := resp.Append(ctx.Out)
 95→	if aerr != nil {
 96→		return status.InsuffServerResources
 97→	}
 98→	ctx.Out = out
 99→	return nil
100→}
101→
102→// noMoreFiles 区分「首次枚举就无匹配」与「枚举已结束」。
103→func noMoreFiles(first bool) error {
104→	if first {
105→		// 模式没匹配到任何东西。
106→		return status.NoSuchFile
107→	}
108→	return status.NoMoreFiles
109→}
110→
111→// dirEntry 把 VFS 目录项翻译成线格式目录项。
112→func dirEntry(e *vfs.DirEntry) wire.DirEntry {
113→	return wire.DirEntry{
114→		CreationTime:   vfs.TimeToFiletime(e.Attr.CreateTime),
115→		LastAccessTime: vfs.TimeToFiletime(e.Attr.AccessTime),
116→		LastWriteTime:  vfs.TimeToFiletime(e.Attr.WriteTime),
117→		ChangeTime:     vfs.TimeToFiletime(e.Attr.ChangeTime),
118→		EndOfFile:      uint64(e.Attr.Size),
119→		AllocationSize: uint64(e.Attr.Alloc),
120→		FileAttributes: wire.FileAttributes(e.Attr.FileAttributes),
121→		FileID:         e.Attr.FileID,
122→		Name:           e.Name,
123→	}
124→}
