func TestAppleRecords(t *testing.T) {
	const instance = "TESTBOX"

	r, err := New(config.MDNS{
		Enabled:  true,
		Instance: instance,
		Apple: config.AppleMDNS{
			Enabled:              true,
			Model:                "TimeCapsule8,119",
			AdvertiseTimeMachine: true,
