	if got, ok := srv[adiskInstance]; !ok || got != 0 {
		t.Errorf("_adisk SRV 端口 = %d (存在=%v), 期望 0", got, ok)
	}
	if got, ok := srv[devInstance]; !ok || got != 0 {
		t.Errorf("_device-info SRV 端口 = %d (存在=%v), 期望 0", got, ok)
	}

