## 1. `check_aapl()` — Full Source

```c
static NTSTATUS check_aapl(vfs_handle_struct *handle,
			   struct smb_request *req,
			   const struct smb2_create_blobs *in_context_blobs,
			   struct smb2_create_blobs *out_context_blobs)
{
	struct fruit_config_data *config;
	NTSTATUS status;
	struct smb2_create_blob *aapl = NULL;
	uint32_t cmd;
	bool ok;
	uint8_t p[16];
	DATA_BLOB blob = data_blob_talloc(req, NULL, 0);
	uint64_t req_bitmap, client_caps;
	uint64_t server_caps = SMB2_CRTCTX_AAPL_UNIX_BASED;
	smb_ucs2_t *model;
	size_t modellen;

	SMB_VFS_HANDLE_GET_DATA(handle, config, struct fruit_config_data,
				return NT_STATUS_UNSUCCESSFUL);

	if (!config->use_aapl
	    || in_context_blobs == NULL
	    || out_context_blobs == NULL) {
		return NT_STATUS_OK;
	}

	aapl = smb2_create_blob_find(in_context_blobs,
				     SMB2_CREATE_TAG_AAPL);
	if (aapl == NULL) {
		return NT_STATUS_OK;
	}

	if (aapl->data.length != 24) {
		DEBUG(1, ("unexpected AAPL ctxt length: %ju\n",
			  (uintmax_t)aapl->data.length));
		return NT_STATUS_INVALID_PARAMETER;
	}

	cmd = IVAL(aapl->data.data, 0);
	if (cmd != SMB2_CRTCTX_AAPL_SERVER_QUERY) {
		DEBUG(1, ("unsupported AAPL cmd: %d\n", cmd));
		return NT_STATUS_INVALID_PARAMETER;
	}

	req_bitmap = BVAL(aapl->data.data, 8);
	client_caps = BVAL(aapl->data.data, 16);

	SIVAL(p, 0, SMB2_CRTCTX_AAPL_SERVER_QUERY);
	SIVAL(p, 4, 0);
	SBVAL(p, 8, req_bitmap);
	ok = data_blob_append(req, &blob, p, 16);
	if (!ok) {
		return NT_STATUS_UNSUCCESSFUL;
	}

	if (req_bitmap & SMB2_CRTCTX_AAPL_SERVER_CAPS) {
		if ((client_caps & SMB2_CRTCTX_AAPL_SUPPORTS_READ_DIR_ATTR) &&
		    (handle->conn->fs_capabilities & FILE_NAMED_STREAMS)) {
			server_caps |= SMB2_CRTCTX_AAPL_SUPPORTS_READ_DIR_ATTR;
			config->readdir_attr_enabled = true;
		}

		if (config->use_copyfile) {
			server_caps |= SMB2_CRTCTX_AAPL_SUPPORTS_OSX_COPYFILE;
			config->copyfile_enabled = true;
		}

		/*
		 * The client doesn't set the flag, so we can't check
		 * for it and just set it unconditionally
		 */
		if (config->unix_info_enabled) {
			server_caps |= SMB2_CRTCTX_AAPL_SUPPORTS_NFS_ACE;
		}

		SBVAL(p, 0, server_caps);
		ok = data_blob_append(req, &blob, p, 8);
		if (!ok) {
			return NT_STATUS_UNSUCCESSFUL;
		}
	}

	if (req_bitmap & SMB2_CRTCTX_AAPL_VOLUME_CAPS) {
		int val = lp_case_sensitive(SNUM(handle->conn));
		uint64_t caps = 0;

		switch (val) {
		case Auto:
			break;

		case True:
			caps |= SMB2_CRTCTX_AAPL_CASE_SENSITIVE;
			break;

		default:
			break;
		}

		if (config->time_machine) {
			caps |= SMB2_CRTCTX_AAPL_FULL_SYNC;
		}

		SBVAL(p, 0, caps);

		ok = data_blob_append(req, &blob, p, 8);
		if (!ok) {
			return NT_STATUS_UNSUCCESSFUL;
		}
	}

	if (req_bitmap & SMB2_CRTCTX_AAPL_MODEL_INFO) {
		ok = convert_string_talloc(req,
					   CH_UNIX, CH_UTF16LE,
					   config->model, strlen(config->model),
					   &model, &modellen);
		if (!ok) {
			return NT_STATUS_UNSUCCESSFUL;
		}

		SIVAL(p, 0, 0);
		SIVAL(p + 4, 0, modellen);
		ok = data_blob_append(req, &blob, p, 8);
		if (!ok) {
			talloc_free(model);
			return NT_STATUS_UNSUCCESSFUL;
		}

		ok = data_blob_append(req, &blob, model, modellen);
		talloc_free(model);
		if (!ok) {
			return NT_STATUS_UNSUCCESSFUL;
		}
	}

	status = smb2_create_blob_add(out_context_blobs,
				      out_context_blobs,
				      SMB2_CREATE_TAG_AAPL,
				      blob);
	if (NT_STATUS_IS_OK(status)) {
		global_fruit_config.nego_aapl = true;
	}

	return status;
}
```

### `SMB2_CRTCTX_AAPL_*` Constants Used (from code)
These are not defined in the snippet but are referenced with literal associated semantics:

| Constant (token) | Usage in `check_aapl()` | Implied value / role |
|---|---|---|
| `SMB2_CRTCTX_AAPL_UNIX_BASED` | Initial `server_caps` base | Bitflag for UNIX-based server |
| `SMB2_CRTCTX_AAPL_SERVER_QUERY` | `cmd` check & `SIVAL(p,0,...)` | Command type = 1 (typical) |
| `SMB2_CRTCTX_AAPL_SUPPORTS_READ_DIR_ATTR` | Set if client cap & named streams | Bitflag for readdir attr |
| `SMB2_CRTCTX_AAPL_SUPPORTS_OSX_COPYFILE` | Set if `use_copyfile` | Bitflag for copyfile |
| `SMB2_CRTCTX_AAPL_SUPPORTS_NFS_ACE` | Set if `unix_info_enabled` | Bitflag for NFS ACEs |
| `SMB2_CRTCTX_AAPL_SERVER_CAPS` | Bitmap bit for server caps block | Offset 8 in req_bitmap |
| `SMB2_CRTCTX_AAPL_VOLUME_CAPS` | Bitmap bit for volume caps | Offset 8 in req_bitmap |
| `SMB2_CRTCTX_AAPL_MODEL_INFO` | Bitmap bit for model string | Offset 8 in req_bitmap |
| `SMB2_CRTCTX_AAPL_CASE_SENSITIVE` | Volume cap if case sensitive | Bitflag |
| `SMB2_CRTCTX_AAPL_FULL_SYNC` | Volume cap if Time Machine | Bitflag |
| `SMB2_CREATE_TAG_AAPL` | Blob tag for find/add | External string tag |

**Byte offsets / field writes in `check_aapl()`:**
- `IVAL(aapl->data.data, 0)` → command at offset 0
- `BVAL(aapl->data.data, 8)` → req_bitmap at offset 8 (uint64)
- `BVAL(aapl->data.data, 16)` → client_caps at offset 16 (uint64)
- `SIVAL(p, 0, ...)` → p[0..3] = query cmd
- `SIVAL(p, 4, 0)` → p[4..7] = 0
- `SBVAL(p, 8, req_bitmap)` → p[8..15] = bitmap
- `SBVAL(p, 0, server_caps)` → p[0..7] = caps (in caps block)
- `SIVAL(p, 0, 0)` + `SIVAL(p+4, 0, modellen)` → model header (len at p[4..7])

